CREATE TABLE programs (id UUID PRIMARY KEY, title VARCHAR(180) NOT NULL, slug VARCHAR(220) NOT NULL UNIQUE, description VARCHAR(3000), status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', organization_id UUID REFERENCES organizations(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE learning_paths (id UUID PRIMARY KEY, program_id UUID NOT NULL REFERENCES programs(id) ON DELETE CASCADE, title VARCHAR(180) NOT NULL, description VARCHAR(2500), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE learning_path_courses (id UUID PRIMARY KEY, learning_path_id UUID NOT NULL REFERENCES learning_paths(id) ON DELETE CASCADE, course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0, UNIQUE(learning_path_id,course_id));
CREATE INDEX idx_programs_status ON programs(status); CREATE INDEX idx_learning_paths_program ON learning_paths(program_id); CREATE INDEX idx_learning_path_courses_path ON learning_path_courses(learning_path_id);